window.kbPageData["views/entry/k-9fe805a639ce6c15"] = {"key":"entry/k-9fe805a639ce6c15","state":{"route":"entry/k-9fe805a639ce6c15"},"node":{"id":"k-9fe805a639ce6c15","mode":"k","title":"综合整治“内卷式”竞争","type":"制度与规则","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":["“内卷式”竞争"],"qs":["政治理论必刷100题#32"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"专题":["market"],"主类":["制度与规则"],"出处性质":["专项题解析","机构注释"],"学科":["政治理论","经济"],"来源主题":["发展与治理"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"2024年中央经济工作会议在部署现代化产业体系建设时，提出综合整治“内卷式”竞争，并要求规范地方政府和企业行为。","review":{"definition":"2024年中央经济工作会议在部署现代化产业体系建设时，提出综合整治“内卷式”竞争，并要求规范地方政府和企业行为。","explanation":"会议点明了地方政府和企业两类行为主体。C项用“市场主体”概括规范对象，遗漏了会议明确列出的地方政府，因此是本题要求选出的不正确表述。","references":[],"evidence":"规范地方政府和企业行为","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"9a577840592b8b76","label":"“内卷式”竞争","topic":"发展与治理","category":"非时政","text":"3.“内卷式”竞争\n“内卷式”竞争本质是市场失灵下的资源错配，当所有经营主体的收益改进空间消失，\n经营主体便陷入了低水平均衡困境，只能在有限市场中进行同质化竞争，最终使得社会资源\n配置的整体效率降低。\n——求是网","source":{"doc":"6cbfb01fe723bba64b75","first":8,"last":8,"page":8,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#32":{"paper":"政治理论必刷100题","n":32,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",10],"asrc":["国省考政治理论必刷100题.pdf",51],"card":"21c7d985ba2119c3251b1a68","links":[{"id":"k-9fe805a639ce6c15","role":"直接考查","why":"会议明确要求规范地方政府和企业行为，行为主体的表述决定该项正误。"}]}},"terms":{},"references":{},"topics":[{"slug":"market","title":"统一大市场与公平竞争"}],"units":{"k-9fe805a639ce6c15":[["政治理论必刷100题#32"]]}};
